import { ReactNode, FC } from 'react';

interface AccordionItem {
    /** 唯一标识 */
    key: string;
    /** 标题 */
    title: ReactNode;
    /** 内容 */
    content: ReactNode;
    /** 是否禁用 */
    disabled?: boolean;
}
interface AccordionProps {
    /** 选项列表 */
    items: AccordionItem[];
    /** 当前展开项 (受控) */
    activeKey?: string;
    /** 默认展开项 */
    defaultActiveKey?: string;
    /** 展开变化回调 */
    onChange?: (key: string) => void;
    /** 是否显示边框 */
    bordered?: boolean;
    /** 自定义类名 */
    className?: string;
}

declare const Accordion: FC<AccordionProps>;

export { Accordion, Accordion as default };
export type { AccordionItem, AccordionProps };
